import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import API from '../api/axiosClient';
import { FaSignOutAlt, FaWallet, FaCashRegister } from 'react-icons/fa';

export default function Navbar({ role }) {
    const navigate = useNavigate();

    const handleLogout = async () => {
        try {
            await API.post('/auth/logout');
            navigate('/login');
        } catch (err) {
            console.error('Logout failed', err);
        }
    };

    return (
        <nav className="bg-gray-800 border-b border-gray-700 px-8 py-4 flex justify-between items-center text-white">
            <div className="font-bold text-xl flex items-center gap-2">
                <span className="text-indigo-400">Loyalty</span>Mesh
            </div>
            <div className="flex items-center gap-6">
                {role === 'customer' && (
                    <Link to="/customer" className="flex items-center gap-1 hover:text-indigo-400 transition">
                        <FaWallet /> Dashboard
                    </Link>
                )}
                {(role === 'worker' || role === 'admin') && (
                    <Link to="/worker" className="flex items-center gap-1 hover:text-indigo-400 transition">
                        <FaCashRegister /> Terminal
                    </Link>
                )}
                <button 
                    onClick={handleLogout}
                    className="flex items-center gap-1 bg-red-600 hover:bg-red-500 px-4 py-2 rounded-lg text-sm font-semibold transition"
                >
                    <FaSignOutAlt /> Logout
                </button>
            </div>
        </nav>
    );
}
